from math import sqrt
from itertools import combinations
import random, statistics

def sample(rows, n, subjects, cap=None):
    if n:
        assert n<=len(rows)
        random.seed(0)
        random.shuffle(rows)
        rows=rows[:n]
    eligible=[q for q in rows if q[0] in subjects]
    jobs=[]
    counts={s:0 for s in subjects}
    for row in eligible:
        s=row[0]
        if cap and counts[s]>=cap: continue
        counts[s]+=1
        jobs.append(row)
    return [s+str(i) for s,i in rows], len(eligible), [s+str(i) for s,i in jobs]
