def report(c,t,N):
    p=c/t
    return sqrt(p*(1-p)/t*(N-t)/(N-1))
print('50/100 of 1000, percentage points:',round(100*report(50,100,1000),6),'normal 1.96 multiple:',round(196*report(50,100,1000),6))
